P = [
 dict(pmid='43063215', doi='10.1371/journal.pone.0362587', journal='PLoS One', title='Ambient particulate chemical components and dengue incidence: A 10-year nationwide study in Thailand.', tier='B', basis='Model (CTM / LUR / ML)', short='Thailand 77 provinces 2012-2021, 837,616 dengue cases: MERRA-2 dust PM2.5 positively, OC, BC and sulfate inversely associated with incidence', design='Bayesian spatiotemporal model', pm='Monthly MERRA-2 reanalysis dust PM2.5, organic carbon, black carbon and sulfate by province', geo='Thailand (77 provinces)', endpoint='Monthly provincial dengue incidence', affil='Khon Kaen University, Thailand; Khon Kaen University, Thailand', n='Ecological analysis of 837,616 dengue cases reported across 77 Thai provinces, 2012-2021, against monthly MERRA-2 aerosol components; Bayesian spatial INLA models adjusted for demographic and temporal factors. Dust PM2.5 was positively associated with dengue incidence, while organic carbon, black carbon and sulfate were inversely associated; the abstract reports no effect sizes or credible intervals. Weakness: ecological province-month design in which aerosol components co-vary with season, rainfall and burning, all of which drive Aedes ecology; MERRA-2 composition at province scale is a reanalysis product with no local validation; mechanism is speculative. Relevance: composition-resolved inputs for disease early warning cannot come from mass-only low-cost sensors; at most they supply total PM2.5 for local calibration of the reanalysis.', sub=corpus.OTHR),
 dict(pmid='43062065', doi='10.7189/jogh.16.04340', journal='J Glob Health', title='The associations of outdoor and indoor air pollution with cognitive function among older adults in China.', tier='B', basis='Not stated', short='CHARLS 8806 adults >=60: higher outdoor PM1/PM2.5/PM10 and solid-fuel cooking (global cognition beta -0.57) precede poorer cognition, stronger in rural residents', design='Prospective cohort (CHARLS)', pm='Annual mean PM1, PM2.5 and PM10 (source not stated in abstract); household solid fuel for cooking and heating', geo='China (national, CHARLS)', endpoint='Global cognition, memory and mental status, 2013-2020', affil='Wuhan Mental Health Center, China; Wuhan Mental Health Center, China', n='8,806 CHARLS participants aged >=60, 2013-2020; linear mixed-effects models of 2013 exposures on later cognition, stratified by urban-rural residence. Higher outdoor particulate matter was generally associated with poorer subsequent global cognition and memory; 2013 PM2.5 was inversely associated with global cognition in both 2015 and 2018 (coefficients not given in the abstract). Solid-fuel cooking in 2013 predicted lower 2018 global cognition (beta -0.57, 95% CI -0.93 to -0.22), memory (-0.53, -0.77 to -0.31) and mental status (-0.23, -0.40 to -0.06); heating fuel gave similar estimates. Associations were stronger in rural participants. Weakness: household fuel is a binary proxy with no measured indoor PM, attrition in an older cohort is likely exposure- and cognition-related, and outdoor PM effect sizes are not reported. Relevance: rural indoor combustion is where measured personal exposure is thinnest and cheap sensors most informative.', sub=corpus.NEU),
 dict(pmid='43060507', doi='10.3389/fpubh.2026.1784006', journal='Front Public Health', title='Prenatal exposure to polycyclic aromatic hydrocarbons and heating-season air pollution: associations with birth outcomes in a coal-reliant city.', tier='C', basis='Reference / regulatory monitor', short='Urumqi 279 mother-infant pairs: longer heating-season gestational overlap linked to shorter birth length (-0.011 cm per day); PAHs detected in 47-91% of plasma samples', design='Prospective birth cohort', pm='Gestational overlap with the municipal heating season; ambient PM2.5 and PM10; 16 PAHs in maternal and cord plasma (GC-MS)', geo='China (Urumqi)', endpoint='Neonatal anthropometry (length, weight, Ponderal Index)', affil='Xinjiang Medical University, China; Xinjiang Medical University, China', n='279 mother-infant pairs enrolled June 2019-January 2020 in Urumqi, a coal-heated city; long vs short gestational overlap with the heating season; 16 PAHs by GC-MS in paired maternal and cord plasma. Detection rates were 66-91% in maternal and 48-78% in cord plasma. Longer heating-season exposure was associated with lower birth length (p = 0.002) and Ponderal Index but not birth weight (p = 0.132); each additional day of heating-season overlap was associated with -0.011 cm length (p = 0.004); higher gestational PM2.5 and PM10 also tracked shorter length. No CIs reported. Weakness: heating-season overlap is collinear with season of birth, small n, and enrolment over seven months confounds exposure with calendar time. Relevance: winter coal-heating peaks are steep and spatially patchy - the setting where home-level sensors would replace a seasonal proxy.', sub=corpus.REPR),
 dict(pmid='43063063', doi='10.1097/md.0000000000051553', journal='Medicine (Baltimore)', title='Mendelian randomization study reveals the effects of air pollution on the risk of male and female infertility.', tier='C', basis='Genetic / biomarker proxy', short='Two-sample MR (UK Biobank exposures, FinnGen outcomes): genetically predicted PM2.5 nominally raises male infertility (p = 0.04), not after Bonferroni; nothing for female infertility', design='Two-sample Mendelian randomisation', pm='Genetic instruments for PM2.5, PM2.5-10, PM10, NO2 and NOx (UK Biobank address-based exposures)', geo='Global / multi-region', endpoint='Male and female infertility (FinnGen)', affil='Second Affiliated Hospital of Jianghan University, China; Second Affiliated Hospital of Jianghan University, China', n='Two-sample Mendelian randomisation using instruments for five pollutants from UK Biobank and male and female infertility from FinnGen; four MR estimators plus heterogeneity and pleiotropy tests. Genetically predicted PM2.5 was associated with male infertility at p = 0.04, which did not survive Bonferroni correction; no associations for NOx, NO2, PM10 or PM2.5-10 with male infertility, and none for any pollutant with female infertility. No effect sizes are given in the abstract. Weakness: SNPs associated with a residential pollution estimate index where people live (ancestry, SES, migration), not biological susceptibility, so the exclusion restriction is implausible; the headline result is a nominal p-value. Relevance: none to measurement; it illustrates why genetic proxies cannot substitute for exposure data.', sub=corpus.REPR),
]
